-- Môone — Séfora Lencería: carga inicial de artículos en venta (desde Excel).
-- Una fila por modelo + color + talle; las unidades repetidas suman stock.
-- grupo_producto agrupa los talles de un mismo modelo y color en una sola
-- tarjeta con selector de talle. Las fotos se agregan después, por modelo.
-- Se muestran en /sefora-lenceria (filtradas por marca).
-- El costo del Excel NO se carga: products es de lectura pública (anon).

insert into products
  (sku, nombre, categoria, subcategoria, talle, color, precio_venta, stock, grupo_producto, slug,
   marca, condicion, precio_alquiler, valor_reposicion, estado, disponible, visible_web)
